class Solution {
    public boolean isRectangleOverlap(int[] rec1, int[] rec2) {
        // Two rectangles do not overlap if one is completely to the left, right,
        // above or below the other.
        // So, they overlap if and only if:
        // rec1's left edge is left of rec2's right edge AND
        // rec1's right edge is right of rec2's left edge AND
        // rec1's bottom edge is below rec2's top edge AND
        // rec1's top edge is above rec2's bottom edge.

        return rec1[0] < rec2[2] &&  // rec1 left < rec2 right
               rec1[2] > rec2[0] &&  // rec1 right > rec2 left
               rec1[1] < rec2[3] &&  // rec1 bottom < rec2 top
               rec1[3] > rec2[1];    // rec1 top > rec2 bottom
    }
}

